INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Methode Fünf Warum immer genau fünf Fragen erfordert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel, je nach Ursache"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend fünf"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Methode Fünf Warum in einer IT-Firma anwende?', 3, '[{"text": "Ursachenfindung", "correct": true, "because": "Kern der Methode"}, {"text": "Schnellste Lösung", "correct": false, "because": "Analyse zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei der Methode Fünf Warum wichtig?', 5, '[{"text": "Systematisches Nachfragen", "correct": true, "because": "Führt zur Ursache"}, {"text": "Problemdefinition", "correct": true, "because": "Startpunkt der Analyse"}, {"text": "Büromöbel", "correct": false, "because": "Kein Faktor"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Methode Fünf Warum findet Grundursachen. b) Sie ist immer zeitaufwendig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer zeitaufwendig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Methode Fünf Warum in einem IT-System anwende?', 4, '[{"text": "Problemursachen", "correct": false, "because": "Kern der Methode"}, {"text": "Fehlerprotokolle", "correct": false, "because": "Liefern Hinweise"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Methode Fünf Warum nur für IT-Probleme geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Bereiche"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Methode Fünf Warum?', 3, '[{"text": "Ursachenidentifikation", "correct": true, "because": "Löst Probleme"}, {"text": "Schnellste Lösung", "correct": false, "because": "Analyse wichtiger"}, {"text": "Weniger Fragen", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte umfasst die Methode Fünf Warum?', 5, '[{"text": "Problem festlegen", "correct": true, "because": "Startpunkt"}, {"text": "Warum-Fragen stellen", "correct": true, "because": "Führt zur Ursache"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Methode Fünf Warum ist einfach anzuwenden. b) Sie erfordert immer Experten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Experte nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Methode Fünf Warum in der IT anzuwenden?', 4, '[{"text": "Problemdefinition", "correct": false, "because": "Startpunkt"}, {"text": "Logisches Denken", "correct": false, "because": "Führt zur Ursache"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Methode Fünf Warum immer zeitaufwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Kann schnell sein"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Methode Fünf Warum in der IT?', 4, '[{"text": "Ursachenfindung", "correct": true, "because": "Löst Probleme"}, {"text": "Kosteneffizienz", "correct": true, "because": "Einfache Methode"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Methode Fünf Warum nur für technische Probleme geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorisch"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Methode Fünf Warum effektiv anzuwenden?', 3, '[{"text": "Klares Problem", "correct": true, "because": "Startpunkt definiert"}, {"text": "Schnellste Antworten", "correct": false, "because": "Tiefe wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Methode Fünf Warum fördert Problemlösung. b) Sie erfordert immer fünf Fragen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fragen variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Methode Fünf Warum?', 5, '[{"text": "Problemursachen", "correct": true, "because": "Ziel der Methode"}, {"text": "Logische Abfolge", "correct": true, "because": "Führt zur Lösung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich die Methode Fünf Warum anwende?', 3, '[{"text": "Fehlerdefinition", "correct": false, "because": "Startpunkt"}, {"text": "Fragenstruktur", "correct": false, "because": "Führt zur Ursache"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Methode Fünf Warum nur für komplexe Probleme geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Auch einfache Probleme"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Methode Fünf Warum Expertenwissen erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Einfach anwendbar"}, {"text": "Ja", "correct": false, "because": "Für alle nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für die Methode Fünf Warum?', 4, '[{"text": "Systematisches Nachfragen", "correct": true, "because": "Führt zur Ursache"}, {"text": "Schnellste Antworten", "correct": false, "because": "Tiefe zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
